INSERT INTO academy_way_paths (slug,position,title,purpose,coverage,namespace_name) VALUES
  ('math', 1, 'Make the Numbers Hold', 'Measure, model, and prove a result.', 'Counting and place value; operations; fractions and ratios; algebra; geometry and trigonometry; functions; statistics and probability; precalculus; calculus; vectors, matrices, and differential equations.', 'tabor-academy-way-math-dev'),
  ('science', 2, 'Test How the World Works', 'Build a model or run a fair test.', 'Biology and ecology; chemistry and materials; physics and circuits; Earth systems and climate; astronomy; environmental science; human biology and health literacy; engineering design.', 'tabor-academy-way-science-dev'),
  ('language', 3, 'Say It, Read It, Prove It', 'Work from sound to meaning to a defensible claim.', 'Phonemic awareness and phonics; decoding; fluency; vocabulary and morphology; grammar; reading evidence; argument; composition; editing and speaking.', 'tabor-academy-way-language-dev'),
  ('humanities', 4, 'Trace the Story Back', 'Reconstruct a decision, image, or event from its sources.', 'Local, U.S., world, and European history; U.S. government and comparative civics; geography and culture; art history; music; visual storytelling; oral history.', 'tabor-academy-way-humanities-dev'),
  ('economics', 5, 'Follow the Trade', 'Make a choice, show its cost, and account for what changed.', 'Scarcity and trade-offs; supply and demand; markets; microeconomics and macroeconomics; inflation; budgets, credit, taxes, banking, financial literacy, and capital markets.', 'tabor-academy-way-economics-dev'),
  ('computing', 6, 'Build the Machine Behind the Screen', 'Represent information, write a rule, and test what it does.', 'Programming, drawing and animation; HTML and CSS; data and SQL; algorithms; games and visualization; networks; information theory; cryptography fundamentals; AI literacy.', 'tabor-academy-way-computing-dev'),
  ('readiness', 7, 'Prove You’re Ready', 'Show what you can do, then practice the exact skill that needs work.', 'Prerequisite checks; bridge practice; timed reasoning; reading and math test strategies; admissions, professional, and international assessment practice.', 'tabor-academy-way-readiness-dev'),
  ('life', 8, 'Run the Day', 'Build a plan, test a decision, and explain its effect on other people.', 'Communication; empathy and collaboration; setbacks and practice; digital safety and media literacy; consent and privacy; college and career planning; everyday decisions and project handoffs.', 'tabor-academy-way-life-dev')
INSERT INTO academy_way_missions (slug,path,position,title,outcome,build,flip,integrate,verify,link) VALUES
  ('square-a-corner', 'math', 1, 'Square a corner you can prove', 'A rectangular corner checked with a cord and a second method.', 'Make a loop with 12 equal intervals. Use 3, 4, and 5 intervals as the sides of a triangle.', 'Remove the paper corner guide. Predict which angle stays square when the cord gets larger.', 'Use a second loop with twice the spacing and compare. Geometry supplies the ratio; physical measurement supplies the tolerance.', 'Check both corners against folded paper. A square result and the same side ratio on both setups earn the proof.', 'workbench/47/'),
  ('measure-change', 'math', 2, 'Measure change without guessing', 'A table and graph that explain two rates of change.', 'Mark the water level in a straight-sided container after each equal cup is added. Record the starting level and four readings.', 'Remove a repeated reading only if you can explain why it is a duplicate. Keep an unexpected reading as evidence.', 'Graph amount added against water level. Repeat in a tapered container and explain where the slope changes.', 'Label both axes and units. Predict a fifth reading for the straight-sided container, then compare it with the measurement.', NULL),
  ('compare-cooling', 'science', 3, 'Find out what slows cooling', 'A fair comparison with two temperature traces.', 'Pour equal amounts of warm tap water into two identical cups. Wrap one in dry cloth and check both temperatures together.', 'Remove extra changes: same location, volume, starting temperature, thermometer, and intervals.', 'Log both readings at the same times. Repeat with the cups swapped on the table and explain why the swap matters.', 'Show the two traces. If the repeated trial agrees, explain the effect; if it differs, give one plausible reason and a test.', 'survival/55/'),
  ('paper-bridge', 'science', 4, 'Build a bridge that carries a load', 'A paper structure that supports a declared test load.', 'Span two books with paper. Put coins on one at a time and record the first point of visible sag.', 'Remove materials you can live without. Keep paper size and span constant when comparing shapes.', 'Fold a second sheet into an accordion. Retest the same span and relate the folds to stiffness.', 'A second person can repeat your setup using your measurements and get the same ordering of the two designs.', 'workbench/zones/11/'),
  ('sound-to-word', 'language', 5, 'Turn a sound change into a word change', 'A sound map someone else can read back.', 'Say map and mat slowly. Move a counter for each sound, then replace the last counter with its new sound.', 'Remove letter names from the first pass and listen only for the sound that changed.', 'Write the two words and match each sound to its letter. Try ship and notice that two letters can represent one sound.', 'Give a partner a new pair such as sit and sin. They can locate the changed sound and use the spelling to read both aloud.', NULL),
  ('defend-a-claim', 'language', 6, 'Make a reading claim that survives a challenge', 'A short argument that a reader can trace to its evidence.', 'Choose a short public-domain passage. Write a claim about what a character wants and underline the line that supports it.', 'Cross out any wording that claims more than the line shows. Save an alternative reading beside it.', 'Add a second detail from the passage and explain how it changes the strength of the claim.', 'A partner can find the two details and distinguish the text from your inference.', NULL),
  ('two-sources', 'humanities', 7, 'Reconstruct an event from two sources', 'A dated account with evidence and uncertainty visible.', 'Choose a local historical event. Gather a primary record and a dated account of the same event.', 'Remove claims that neither record supports. Mark who wrote each source and what they could have observed.', 'Put the records on a timeline and compare their reasons for describing the event.', 'A second reader can trace each sentence to a record or identify it as an inference.', NULL),
  ('one-decision', 'humanities', 8, 'Show how a public decision gets made', 'A short hearing that ends in a recorded rule and reason.', 'Use a fictional town deciding where to put a public bench. Give each role one practical concern.', 'Remove labels such as good or bad and identify the actual trade-offs: access, distance, and space.', 'Draw two proposed locations. Let each role respond before the group records one decision and its rationale.', 'Someone not at the hearing can read the decision, name who was heard, and identify one concern still open.', NULL),
  ('budget-with-tradeoffs', 'economics', 9, 'Balance a small budget with a surprise expense', 'A budget that still reconciles after the plan changes.', 'Use fictional amounts: start with 40 tokens, reserve 25 for essentials, and plan what to do with the remaining 15.', 'Introduce a 7-token expense. Identify which choice must change and which commitment remains fixed.', 'Rebuild the budget and track the impact on saving or spending.', 'Show where all 40 tokens went. The before-and-after totals must both reconcile.', NULL),
  ('run-a-market', 'economics', 10, 'Run two trades and explain the price change', 'A table showing what changed when supply changed.', 'Use counters as goods and paper slips as money. Let a small group make offers for six identical counters.', 'Repeat with three counters. Keep the same buyers and starting money so one major condition changes.', 'Compare offers, completed trades, and unsold goods across rounds.', 'Use your recorded prices to support a claim and name one factor you did not control.', NULL),
  ('write-a-state-rule', 'computing', 11, 'Build a rule that changes state', 'A tested state table for a simple program.', 'Make three paper states: waiting, running, done. Define what the Start and Finish buttons do.', 'Remove an ambiguous transition. Decide what happens if Finish is pressed while waiting.', 'Trace the table for normal and unusual sequences; then express it as pseudocode or a short program.', 'A partner can predict all outcomes, including a second Start press, from your stated rules alone.', NULL),
  ('encode-and-check', 'computing', 12, 'Send a message someone can verify', 'A message that can be decoded and checked for copying errors.', 'Set a public letter-shift rule and encode a made-up word. Record how many letters it contains.', 'Introduce one known copying error. Compare cases where the length check notices a change and where it misses one.', 'Compare the original, altered, and decoded copies. Explain why encoding and detecting errors solve different problems.', 'A partner decodes the word and demonstrates one error the length check misses.', 'survival/94/'),
  ('bridge-check', 'readiness', 13, 'Find the prerequisite you need next', 'A short practice plan based on a worked example and evidence.', 'Choose a path and attempt its finished task before looking at the demonstration. Record the first point where you got stuck.', 'Clear away tasks you can already explain. Name one missing operation, term, or observation.', 'Practise that one part with two fresh examples, then return to the original task.', 'You can finish the original task and a new version with one changed detail, explaining both.', NULL),
  ('timed-evidence', 'readiness', 14, 'Answer under time without losing the evidence', 'Two comparable practice attempts and a useful error log.', 'Write a brief argument from two statements in five minutes. Label your claim and supporting statement.', 'Review without the timer. Mark each error as reading, reasoning, timing, or checking.', 'Practice one error type with an original example, then repeat with a fresh five-minute question.', 'Compare scored evidence, not just speed. Explain one improvement you can repeat on the next attempt.', NULL),
  ('fair-decision', 'life', 15, 'Make a fair decision and explain it', 'A shared decision both people can reconstruct.', 'One person divides eight counters and another chooses first. Swap roles for the second round.', 'Name whose preference was missing if either person thought the outcome was unfair.', 'Change one rule together and replay. Keep the same number of counters so the rule change can be compared.', 'Both people can explain the rule, the outcome, and one way to revise it.', 'workbench/zones/92/'),
  ('check-before-sharing', 'life', 16, 'Check a message before sharing it', 'A simple record showing whether a claim is ready to pass along.', 'Use a fictional message claiming a public event has moved. Write down exactly what it claims and what is missing.', 'Remove personal details and separate urgency from evidence.', 'Identify an independent official source that could confirm the time and place. Write two replies: one when confirmed and one when unresolved.', 'A partner can explain why each reply fits the available evidence and what you would protect from sharing.', NULL)
