CREATE TABLE IF NOT EXISTS academy_way_paths (
  slug TEXT PRIMARY KEY, position INTEGER NOT NULL UNIQUE,
  title TEXT NOT NULL, purpose TEXT NOT NULL, coverage TEXT NOT NULL,
  namespace_name TEXT NOT NULL UNIQUE, namespace_id TEXT
);

CREATE TABLE IF NOT EXISTS academy_way_missions (
  slug TEXT PRIMARY KEY, path TEXT NOT NULL REFERENCES academy_way_paths(slug),
  position INTEGER NOT NULL, title TEXT NOT NULL, outcome TEXT NOT NULL,
  build TEXT NOT NULL, flip TEXT NOT NULL, integrate TEXT NOT NULL, verify TEXT NOT NULL,
  link TEXT, UNIQUE(path,position)
);

ON CONFLICT(slug) DO NOTHING;

ON CONFLICT(slug) DO NOTHING;
